    int i;
    struct termios oldt;
    int running = 1;
    int cols = 80;
    int rows = 24;

    srand(time(NULL));

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "-?") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-V") == 0) {
            print_version();
            return 0;
        } else if (strcmp(argv[i], "-a") == 0) {
            async_scroll = 1;
        } else if (strcmp(argv[i], "-b") == 0) {
            bold_chars = 1;
        } else if (strcmp(argv[i], "-B") == 0) {
            all_bold = 1;
            bold_chars = 1;
        } else if (strcmp(argv[i], "-c") == 0) {
            use_japanese = 1;
        } else if (strcmp(argv[i], "-f") == 0) {
            force_term = 1;
        } else if (strcmp(argv[i], "-l") == 0) {
            linux_mode = 1;
        } else if (strcmp(argv[i], "-L") == 0) {
            lock_mode = 1;
        } else if (strcmp(argv[i], "-o") == 0) {
            old_style = 1;
        } else if (strcmp(argv[i], "-n") == 0) {
            no_bold = 1;
        } else if (strcmp(argv[i], "-s") == 0) {
            screensaver_mode = 1;
        } else if (strcmp(argv[i], "-x") == 0) {
            x_mode = 1;
        } else if (strcmp(argv[i], "-r") == 0) {
            rainbow_mode = 1;
        } else if (strcmp(argv[i], "-m") == 0) {
            lambda_mode = 1;
        } else if (strcmp(argv[i], "-k") == 0) {
            chars_change = 1;
        } else if (strcmp(argv[i], "-u") == 0) {
            if (i + 1 < argc) {
                delay = atoi(argv[++i]);
                if (delay < 0) delay = 0;
                if (delay > 10) delay = 10;
            }
        } else if (strcmp(argv[i], "-C") == 0) {
            if (i + 1 < argc) {
                color[15] = '\0';
                strcpy(color, argv[++i]);
                use_color = 1;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) {
                strncpy(tty_name, argv[++i], sizeof(tty_name) - 1);
                tty_set = 1;
            }
        } else if (strcmp(argv[i], "-M") == 0) {
            if (i + 1 < argc) {
                strncpy(message, argv[++i], sizeof(message) - 1);
                message_set = 1;
            }
        } else {
            print_usage();
            return 1;
        }
    }

    if (no_bold && !all_bold) {
        bold_chars = 0;
    }

    if (tty_set) {
        setenv("TERM", tty_name, 1);
    }

    if (force_term) {
        setenv("TERM", "linux", 1);
    }

    init_terminal();

    if (lock_mode) {
        printf("Lock mode enabled\n");
    }

    if (screensaver_mode) {
        printf("Screensaver mode enabled\n");
    }

    if (message_set) {
        printf("Message mode enabled\n");
    }

    clear_screen();

    while (running) {
        if (screensaver_mode) {
            int c;
            c = getchar();
            if (c != EOF) {
                running = 0;
            }
        } else {
            usleep(delay * 100000);
        }

        if (message_set) {
            draw_message(message);
        } else {
            draw_matrix(cols, rows);
        }

        fflush(stdout);
    }

    restore_terminal(&oldt);
    return 0;
}
